const seeThrough=[];async function heroShowsPage(label){const box=await page.locator('.hero-cutout').boundingBox();const vp=page.viewportSize();const glass=await page.locator('.hero-art .spin-badge,.hero-art .hero-pick,.header-inner').evaluateAll(es=>es.filter(e=>getComputedStyle(e).display!=='none').map(e=>{const r=e.getBoundingClientRect();return[r.left-2,r.top-2,r.right+2,r.bottom+2]}));const pts=await decoder.evaluate(([box,vp,glass])=>{const {W,H,sat}=window.cut,s=Math.min(box.width/W,box.height/H),dw=W*s,dh=H*s,ox=box.x+(box.width-dw)/2,oy=box.y+box.height-dh,side=Math.ceil(30/s),up=Math.ceil(64/s),down=Math.ceil(8/s),step=Math.max(3,Math.round(10/s));const q=(x0,y0,x1,y1)=>{x0=Math.max(0,x0);y0=Math.max(0,y0);x1=Math.min(W,x1);y1=Math.min(H,y1);return sat[y1*(W+1)+x1]-sat[y0*(W+1)+x1]-sat[y1*(W+1)+x0]+sat[y0*(W+1)+x0]};const out=[];for(let y=1;y<H-1;y+=step)for(let x=1;x<W-1;x+=step){if(y>H*.86&&x>W*.14&&x<W*.88)continue;if(q(x-side,y-up,x+side+1,y+down+1))continue;const sx=ox+x*s,sy=oy+y*s;if(glass.some(([l,t,r,b])=>sx>=l&&sx<=r&&sy>=t&&sy<=b))continue;if(sx>=1&&sy>=1&&sx<vp.width-1&&sy<vp.height-1)out.push([sx,sy])}return out},[box,vp,glass]);assert(pts.length>=25,`${label}: too few see-through sample points (${pts.length})`);const shown=await pixels(await page.screenshot(),pts);await page.locator('.hero-cutout').evaluate(e=>e.style.visibility='hidden');const hidden=await pixels(await page.screenshot(),pts);await page.locator('.hero-cutout').evaluate(e=>e.style.visibility='');const diff=Math.max(...shown.flatMap((p,k)=>p.map((v,c)=>Math.abs(v-hidden[k][c]))));assert(diff<=2,`${label}: cutout transparent area is not see-through (max channel diff ${diff})`);seeThrough.push({label,points:pts.length,maxDiff:diff});return diff}
async function heroNotClipped(label){const r=await page.evaluate(()=>{const h=document.querySelector('.hero'),st=document.querySelector('.hero-stage'),hb=h.getBoundingClientRect(),sb=st.getBoundingClientRect();return{overflowY:getComputedStyle(h).overflowY,heroBottom:hb.bottom+scrollY,stageBottom:sb.bottom+scrollY,stageLeft:sb.left,stageWidth:sb.width}});assert.equal(r.overflowY,'visible',`${label}: hero clips vertically`);assert(r.stageBottom<=r.heroBottom+0.5,`${label}: stand extends past the hero (${r.stageBottom}>${r.heroBottom})`);await page.evaluate(y=>scrollTo(0,Math.max(0,y-innerHeight/2)),r.heroBottom);await page.waitForTimeout(80);const top=await page.evaluate(()=>scrollY);const yb=r.heroBottom-top;const xs=[...Array(9)].map((_,k)=>r.stageLeft+r.stageWidth*(.36+k*.035));const above=await pixels(await page.screenshot(),xs.map(x=>[x,yb-2]));const below=await pixels(await page.screenshot(),xs.map(x=>[x,yb+2]));const avg=a=>a.reduce((t,p)=>t+(p[0]+p[1]+p[2])/3,0)/a.length;const step=Math.abs(avg(above)-avg(below));assert(step<=2,`${label}: hard edge under the stand at the hero bottom (${step.toFixed(1)})`);await page.evaluate(()=>scrollTo(0,0));return step}
