const r11sparkle=await page.evaluate(async({rest,frames})=>{const dec=async b64=>{const i=new Image();i.src='data:image/png;base64,'+b64;await i.decode();const c=document.createElement('canvas');c.width=i.width;c.height=i.height;const x=c.getContext('2d');x.drawImage(i,0,0);return{w:c.width,h:c.height,d:x.getImageData(0,0,c.width,c.height).data}};const L=(d,i)=>.2126*d[i]+.7152*d[i+1]+.0722*d[i+2];const R=await dec(rest),W=R.w,H=R.h;let share=0,mean=0;
 for(const f of frames){const F=await dec(f);let best=null;for(let dy=-8;dy<=1;dy++){let s=0,n=0;for(let y=Math.round(H*.12);y<Math.round(H*.76);y+=3)for(let x=14;x<W-14;x+=3){const yy=y-dy;if(yy<0||yy>=H)continue;s+=Math.abs(L(F.d,(y*W+x)*4)-L(R.d,(yy*W+x)*4));n++}if(!best||s/n<best.m)best={dy,m:s/n}}let b=0,n=0;for(let y=Math.round(H*.12);y<Math.round(H*.76);y+=3)for(let x=14;x<W-14;x+=3){const yy=y-best.dy;if(yy<0||yy>=H)continue;if(L(F.d,(y*W+x)*4)-L(R.d,(yy*W+x)*4)>25)b++;n++}share=Math.max(share,b/n);mean=Math.max(mean,best.m)}return{frames:frames.length,alignedBrighteningShareMax:share,alignedResidualMeanMax:mean}},{rest:r11restShot,frames:r11frames});
